"""Writes wgmma_e4m3.cuh: wgmma m64n256k32 e4m3·e4m3 into f32 accumulators (the s8 wrappers are int8_class_rate's)."""
from pathlib import Path

N = 256
REGS = N // 2

regs = ",".join(f"%{i}" for i in range(REGS))
cons = ", ".join(f'"+f"(d[{i}])' for i in range(REGS))
out = [
    "// generated by gen_wgmma.py",
    "#pragma once",
    "#include <cstdint>",
    "",
    f"__device__ __forceinline__ void wgmma_e4m3_m64n{N}k32(float* d, uint64_t da, uint64_t db) {{",
    "  asm volatile(",
    f'    "{{\\n.reg .pred p;\\nsetp.ne.b32 p, %{REGS + 2}, 0;\\n"',
    f'    "wgmma.mma_async.sync.aligned.m64n{N}k32.f32.e4m3.e4m3 {{{regs}}}, %{REGS}, %{REGS + 1}, p, 1, 1;\\n}}\\n"',
    f"    : {cons}",
    '    : "l"(da), "l"(db), "r"(1));',
    "}",
    "",
]
Path(__file__).with_name("wgmma_e4m3.cuh").write_text("\n".join(out))
